function mF(t) {
  if (!new RegExp("\\p{Script=Han}", "u").test(t)) {
    return t;
  }
  if (Object.hasOwn(dy, t)) {
    return dy[t];
  }
  let e;
  if (e = /^计算周期 (\w+)$/.exec(t)) {
    return `Calculation timeframe ${e[1]}`;
  }
  if (e = /^低周期覆盖 (\d+)\/(\d+)$/.exec(t)) {
    return `Lower-timeframe coverage ${e[1]}/${e[2]}`;
  }
  if (e = /^已确定 (\d+) \/ 5 段$/.exec(t)) {
    return `${e[1]} of 5 segments set`;
  }
  if (e = /^(启用档位|档位颜色|档位|最小周期|最大周期) (\d+)$/.exec(t)) {
    return `${{
      启用档位: "Enable level",
      档位颜色: "Level color",
      档位: "Level",
      最小周期: "Minimum interval",
      最大周期: "Maximum interval"
    }[e[1]]} ${e[2]}`;
  }
  if (e = /^(价格|时间) #(\d+)$/.exec(t)) {
    return `${e[1] === "价格" ? "Price" : "Time"} #${e[2]}`;
  }
  if (e = /^(收藏|取消收藏|展开)(.+)$/.exec(t)) {
    const n = dy[e[2]];
    if (n) {
      if (e[1] === "展开") {
        return `Open ${n}`;
      } else {
        return `${e[1] === "收藏" ? "Add" : "Remove"} ${n} ${e[1] === "收藏" ? "to" : "from"} favorites`;
      }
    }
  }
  if ((e = /^(.+)输入$/.exec(t)) && dy[e[1]]) {
    return `Edit ${dy[e[1]]}`;
  } else if (e = /^(颜色|文本颜色|背景颜色) (#[\da-f]+)$/i.exec(t)) {
    return `${{
      颜色: "Color",
      文本颜色: "Text color",
      背景颜色: "Background color"
    }[e[1]]} ${e[2]}`;
  } else if (e = /^(\d+) 像素$/.exec(t)) {
    return `${e[1]} px`;
  } else if (e = /^依次点击图表设置 (\d+) 个端点；完成后可拖动端点调整$/.exec(t)) {
    return `Click the chart to set ${e[1]} ${e[1] === "1" ? "point" : "points"}; drag the points to adjust after drawing`;
  } else if (e = /^已设置 (\d+)(?:\/(\d+))? 个端点$/.exec(t)) {
    if (e[2]) {
      return `${e[1]} of ${e[2]} points set`;
    } else {
      return `${e[1]} ${e[1] === "1" ? "point" : "points"} set`;
    }
  } else if (e = /^第 (\d+) 个端点已设置（共 (\d+) 个）$/.exec(t)) {
    return `Point ${e[1]} of ${e[2]} set`;
  } else if (e = /^移动鼠标选择第 (\d+) 个端点，再次点击继续$/.exec(t)) {
    return `Move to point ${e[1]} and click to continue`;
  } else if (e = /^已取消第 (\d+) 个端点，前 (\d+) 个端点已保留$/.exec(t)) {
    return `Point ${e[1]} removed; ${e[2]} ${e[2] === "1" ? "point" : "points"} retained`;
  } else if (e = /^清空(.+)的所有绘图？$/.exec(t)) {
    return `Remove all drawings from ${gF(e[1])}?`;
  } else if (e = /^(.+)的手动绘图及历史记录都将被永久删除，其他分屏不受影响。此操作无法撤销。$/.exec(t)) {
    return `All manual drawings, AI drawings, and drawing history in ${gF(e[1])} will be permanently deleted. Other chart panes will not be affected. This cannot be undone.`;
  } else if (e = /^([\d.]+)(天|小时|分钟|秒)$/.exec(t)) {
    return `${e[1]}${{
      天: "d",
      小时: "h",
      分钟: "m",
      秒: "s"
    }[e[2]]}`;
  } else if (e = /^([\d,—]+)根K线 \((.+)\), 距离: ([\d,]+) px$/.exec(t)) {
    return `${e[1]} bars (${e[2]}), Distance: ${e[3]} px`;
  } else {
    return null;
  }
}
function gF(t) {
  return t.replace(/^副图\s*/, "indicator pane ").replace(/^分屏\s*/, "chart pane ").replace(/^主图$/, "the main chart");
}
function Hce(t, e = false) {
  const n = String(t);
  const i = n.trim();
  const r = e ? zce[i] : mF(i);
  if (r != null) {
    return n.replace(i, () => r);
  }
  if (i.includes(" · ")) {
    const a = i.split(" · ").map(mF);
    if (a.every(o => o != null)) {
      return n.replace(i, () => a.join(" · "));
    }
  }
  return null;
}
