const cde = t => t.id === "alternative:fng" || t.id === "index:fear-greed";
const Rn = (t, e) => On() === "en-US" ? e : ee(t);
const $d = t => {
  if (On() !== "en-US") {
    return ee(t.name);
  }
  const e = t.enName || ee(t.name);
  if (new RegExp("\\p{Script=Han}", "u").test(e)) {
    if (new RegExp("\\p{Script=Han}", "u").test(t.code)) {
      return t.id;
    } else {
      return t.code;
    }
  } else {
    return e;
  }
};
const dde = t => t.value === null ? "--" : t.value.toLocaleString(On(), {
  maximumFractionDigits: 12
});
const ik = t => {
  if (t.value === null) {
    return "--";
  }
  const e = Math.abs(t.value);
  if (e > 0 && e < 0.0001) {
    return t.value.toExponential(2);
  } else if (e >= 10000) {
    return t.value.toLocaleString(On(), {
      notation: "compact",
      maximumSignificantDigits: 5
    });
  } else {
    return t.value.toLocaleString(On(), {
      maximumFractionDigits: cde(t) ? 0 : 4,
      maximumSignificantDigits: 6
    });
  }
};
