/* Chart-only UI patch for the prebuilt renderer bundle.
 *
 * The renderer has no source in this repository, so this script performs the
 * structural changes that CSS alone cannot:
 *   1. move the settings button into the bottom-left corner, above the window
 *      resize layer that would otherwise swallow its clicks;
 *   2. keep split panes in sync with the primary pane (interval, indicators and
 *      visible logical range), so opening a split does not show a completely
 *      different time span;
 *   3. keep one shared indicator bar at the bottom for every pane.
 *
 * The page controller is exposed by a one-line bundle patch as
 * window.__veluneChartPage. */
(function () {
  "use strict";

  const ROOT_CLASS = "velune-chart-only";
  const SETTINGS_SELECTOR = ".conversation-list-settings-button";
  const TOOLBAR_SELECTOR = "aside.trading-drawing-toolbar";
  const MOVED_ATTR = "data-velune-settings-moved";

  // ---------------------------------------------------------------- settings
  function toolbar() {
    return document.querySelector(TOOLBAR_SELECTOR);
  }

  function isPlaced(settings) {
    return Boolean(settings && settings.hasAttribute(MOVED_ATTR) && toolbar()?.contains(settings));
  }

  function needsApply() {
    if (!document.documentElement.classList.contains(ROOT_CLASS)) return true;
    const settings = document.querySelector(SETTINGS_SELECTOR);
    if (!settings) return false;
    return !isPlaced(settings);
  }

  function apply() {
    document.documentElement.classList.add(ROOT_CLASS);

    const host = toolbar();
    if (!host) return;
    const settings = [...document.querySelectorAll(SETTINGS_SELECTOR)]
      .find(element => !element.hasAttribute(MOVED_ATTR));
    if (!settings) return;

    settings.setAttribute(MOVED_ATTR, "1");
    settings.classList.add("velune-toolbar-settings");

    for (const stale of document.querySelectorAll(`${SETTINGS_SELECTOR}[${MOVED_ATTR}]`)) {
      if (stale !== settings) stale.remove();
    }

    host.appendChild(settings);
  }

  // ------------------------------------------------------------ split panes
  const sameSet = (left = [], right = []) => {
    if (left.length !== right.length) return false;
    const a = [...left].sort();
    const b = [...right].sort();
    return a.every((value, index) => value === b[index]);
  };

  const timeRangeEquals = (left, right) => Boolean(
    left && right
    && Math.abs(left.from - right.from) <= 1
    && Math.abs(left.to - right.to) <= 1
  );

  const rangeEquals = (left, right) => Boolean(
    left && right
    && Math.abs(left.from - right.from) < 0.05
    && Math.abs(left.to - right.to) < 0.05
  );

  let lastSettingsJson = "";
  const paneRangeState = new WeakMap();

  function page() {
    return window.__veluneChartPage || null;
  }

  // The renderer occasionally leaves a full-window settings backdrop behind
  // after the dialog closes; it would block titlebar dragging.
  function cleanStaleBackdrops() {
    if (document.querySelector(".settings-dialog")) return;
    document.querySelectorAll(".modal-backdrop.settings-backdrop").forEach(element => element.remove());
  }

  function setTimeRangeOn(chart, range) {
    if (!chart?.timeScale || !range) return false;
    try {
      if (!timeRangeEquals(chart.timeScale().getVisibleRange(), range)) {
        chart.timeScale().setVisibleRange(range);
      }
      return timeRangeEquals(chart.timeScale().getVisibleRange(), range);
    } catch {
      return false;
    }
  }

  function setLogicalRangeOn(chart, range) {
    if (!chart?.timeScale || !range) return false;
    try {
      if (!rangeEquals(chart.timeScale().getVisibleLogicalRange(), range)) {
        chart.timeScale().setVisibleLogicalRange(range);
      }
      return rangeEquals(chart.timeScale().getVisibleLogicalRange(), range);
    } catch {
      return false;
    }
  }

  function syncPane(target, pane, settingsChanged) {
    // Same period as the primary pane.
    const interval = target.activeInterval;
    if (interval && pane.interval !== interval && pane.periods?.some(item => item.resolution === interval)) {
      pane.interval = interval;
      pane.updateToolbarState?.();
      pane.notifySelectionChange?.();
      void pane.reload?.(true);
    }

    // Indicator parameters are shared globally.
    if (settingsChanged && pane.updateIndicatorSettings) {
      pane.updateIndicatorSettings(target.indicatorSettings);
    }

    // Same main/sub indicators as the primary pane.
    if (!sameSet(pane.activeMainIndicators, target.activeMainIndicators)
      || !sameSet(pane.activeIndicators, target.activeIndicators)) {
      pane.activeMainIndicators = [...(target.activeMainIndicators || [])];
      pane.activeIndicators = [...(target.activeIndicators || [])];
      pane.updateMainIndicatorData?.(true);
      pane.rebuildIndicatorPanes?.();
      pane.updateIndicatorData?.();
      pane.updateIndicatorButtons?.();
      pane.notifyIndicatorSelectionChange?.();
    }
  }

  function syncSplitPanes() {
    const target = page();
    if (!target) return;
    const panes = target.splitPanes || [];

    const settingsJson = JSON.stringify(target.indicatorSettings || {});
    const settingsChanged = settingsJson !== lastSettingsJson;
    lastSettingsJson = settingsJson;

    for (const pane of panes) syncPane(target, pane, settingsChanged);

    if (!panes.length) return;
    const primary = target.chart;
    if (!primary?.timeScale) return;

    // Alignment is a one-shot at the moment a pane is created: snapshot the
    // primary range, apply it once the pane data is ready, then never again.
    for (const pane of panes) {
      let state = paneRangeState.get(pane);
      if (!state) {
        state = { createdAt: Date.now(), range: null, kind: "none", matchedAt: 0, done: false };
        paneRangeState.set(pane, state);
      }
      if (state.done || Date.now() - state.createdAt > 15000) {
        state.done = true;
        continue;
      }
      // Keep following the primary until both the primary range and the pane have
      // been stable for a short settle period; then freeze this pane.
      const timeRange = primary.timeScale().getVisibleRange();
      const logicalRange = primary.timeScale().getVisibleLogicalRange();
      if (timeRange) {
        const next = { from: timeRange.from, to: timeRange.to };
        if (state.kind !== "time" || !timeRangeEquals(state.range, next)) state.matchedAt = 0;
        state.kind = "time";
        state.range = next;
      } else if (logicalRange) {
        const next = { from: logicalRange.from, to: logicalRange.to };
        if (state.kind !== "logical" || !rangeEquals(state.range, next)) state.matchedAt = 0;
        state.kind = "logical";
        state.range = next;
      } else if (!state.range) {
        continue;
      }
      const dataReady = (pane.candles?.length || 0) > 0 && pane.loadedInterval === pane.interval;
      if (!dataReady) continue;
      const chart = pane.chart || pane.getChart?.();
      const matched = state.kind === "time"
        ? setTimeRangeOn(chart, state.range)
        : setLogicalRangeOn(chart, state.range);
      if (matched) {
        if (!state.matchedAt) state.matchedAt = Date.now();
        if (Date.now() - state.matchedAt > 1500) state.done = true;
      } else {
        state.matchedAt = 0;
      }
    }
  }

  function boot() {
    apply();

    const observer = new MutationObserver(() => {
      if (needsApply()) apply();
    });
    observer.observe(document.body, { childList: true, subtree: true });

    let attempts = 0;
    const timer = window.setInterval(() => {
      attempts += 1;
      if (needsApply()) apply();
      cleanStaleBackdrops();
      syncSplitPanes();
      if (document.querySelector(`${TOOLBAR_SELECTOR} > ${SETTINGS_SELECTOR}[${MOVED_ATTR}]`) && attempts > 50) {
        window.clearInterval(timer);
        window.setInterval(syncSplitPanes, 300);
      }
    }, 100);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }
})();
/* Market browser filters */
(() => {
  if (window.__veluneMarketFiltersBound) return;
  window.__veluneMarketFiltersBound = true;
  document.addEventListener("change", event => {
    const select = event.target instanceof Element ? event.target.closest("[data-market-filter]") : null;
    if (!select) return;
    const page = window.__veluneChartPage;
    if (!page || typeof page.renderMarkets !== "function") return;
    const key = select.dataset.marketFilter;
    if (key === "country") page.marketFilterCountry = select.value;
    else if (key === "source") page.marketFilterSource = select.value;
    else if (key === "type") page.marketFilterType = select.value;
    else if (key === "exchange") page.marketFilterExchange = select.value;
    page.renderMarkets({ resetScroll: true });
  }, true);
})();
